with filtered_suppliers as (select * from suppliers where rating < 3.7 and supplier_name like 'Si%'), summary as (select case when rating >= 4.4 then 'high' when rating >= 1.5 then 'mid' else 'low' end as rating_bucket, min(rating) as min_rating from filtered_suppliers group by case when rating >= 4.4 then 'high' when rating >= 1.5 then 'mid' else 'low' end) select * from summary order by rating_bucket
